//! 📦️ Original Box allocation custody retires initialized fields without a whole-value transfer.
use semio_framework_value::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
use semio_framework_value::retirement::{RetireOwned,RetirementCursor,controlled::ControlledRetirement};
use semio_framework_job::*;
use std::{mem::size_of,sync::atomic::{AtomicUsize,Ordering}};
static EXPECTED:[AtomicUsize;12]=[const{AtomicUsize::new(0)};12];
struct Probe<const I:usize>([u8;2048]);
impl<const I:usize> RetireOwned for Probe<I>{fn retirement(self)->Box<dyn RetirementCursor>{self.0.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{assert_eq!(self as*const Self as usize,EXPECTED[I].load(Ordering::SeqCst),"field query left the original Box before its funded transfer");self.0.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}}
#[derive(semio_framework_value::RetireOwned)]
#[value(boxed_original,send_only)]
struct Wide{f0:Probe<0>,f1:Probe<1>,f2:Probe<2>,f3:Probe<3>,f4:Probe<4>,f5:Probe<5>,f6:Probe<6>,f7:Probe<7>,f8:Probe<8>,f9:Probe<9>,f10:Probe<10>,f11:Probe<11>}
const BIRTH:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096};
const CLOSE:RetainedCloneGrant=RetainedCloneGrant{maximum_copy_bytes:4096,..BIRTH};
fn turn<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,grant:RetainedCloneGrant,action:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->(T,RetainedCloneProgress){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(grant,decoder,action));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"original boxed source receipt {p:?}, failure={:?}",result.as_ref().err());(result.unwrap(),p)}
#[test]fn original_box_retirement_keeps_each_field_on_the_original_allocation_until_paid_transfer(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();assert_eq!(size_of::<Wide>(),law["fields"].as_u64().unwrap()as usize*law["fieldBytes"].as_u64().unwrap()as usize);assert!(2*size_of::<Wide>()>BIRTH.maximum_copy_bytes);for cutoff in std::iter::once(None).chain(law["cancelAfter"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize))){let mut caller=OriginalJobFixtureCaller::admit(OperationId(99177),Generation(77),RetainedCloneGrant{maximum_items:1<<26,maximum_copy_bytes:1<<29,maximum_capacity_bytes:1<<27,maximum_release_bytes:1<<27,maximum_depth:4096},default_now_us,u64::MAX,1<<26);let mut decoder=OriginalJobDecodeOwner::empty();let mut input=None;let(_,p)=turn(&mut caller,&mut decoder,BIRTH,|cx|{admit_original_construction(cx,&mut input,OriginalConstructionDemand{items:1,copy_bytes:size_of::<Wide>(),capacity_bytes:size_of::<Wide>(),release_bytes:0,depth:1},|_|Ok((Box::write(Box::new_uninit(),Wide{f0:Probe([0;2048]),f1:Probe([1;2048]),f2:Probe([2;2048]),f3:Probe([3;2048]),f4:Probe([4;2048]),f5:Probe([5;2048]),f6:Probe([6;2048]),f7:Probe([7;2048]),f8:Probe([8;2048]),f9:Probe([9;2048]),f10:Probe([10;2048]),f11:Probe([11;2048])}),RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<Wide>(),retained_capacity_bytes:size_of::<Wide>(),..Default::default()})))?;Ok(())});let(mut born,mut freed)=(p.retained_capacity_bytes,p.released_bytes);EXPECTED[0].store(&input.as_ref().unwrap().f0 as*const Probe<0> as usize,Ordering::SeqCst);EXPECTED[1].store(&input.as_ref().unwrap().f1 as*const Probe<1> as usize,Ordering::SeqCst);EXPECTED[2].store(&input.as_ref().unwrap().f2 as*const Probe<2> as usize,Ordering::SeqCst);EXPECTED[3].store(&input.as_ref().unwrap().f3 as*const Probe<3> as usize,Ordering::SeqCst);EXPECTED[4].store(&input.as_ref().unwrap().f4 as*const Probe<4> as usize,Ordering::SeqCst);EXPECTED[5].store(&input.as_ref().unwrap().f5 as*const Probe<5> as usize,Ordering::SeqCst);EXPECTED[6].store(&input.as_ref().unwrap().f6 as*const Probe<6> as usize,Ordering::SeqCst);EXPECTED[7].store(&input.as_ref().unwrap().f7 as*const Probe<7> as usize,Ordering::SeqCst);EXPECTED[8].store(&input.as_ref().unwrap().f8 as*const Probe<8> as usize,Ordering::SeqCst);EXPECTED[9].store(&input.as_ref().unwrap().f9 as*const Probe<9> as usize,Ordering::SeqCst);EXPECTED[10].store(&input.as_ref().unwrap().f10 as*const Probe<10> as usize,Ordering::SeqCst);EXPECTED[11].store(&input.as_ref().unwrap().f11 as*const Probe<11> as usize,Ordering::SeqCst);assert!(input.as_ref().unwrap().retirement_birth_bytes().unwrap()<=CLOSE.maximum_copy_bytes,"boxed source retained its complete inline value");let mut owner=None;let(_,p)=turn(&mut caller,&mut decoder,CLOSE,|cx|{let bytes=2*size_of::<ControlledRetirement<Box<Wide>>>()+2*size_of::<Box<Wide>>();admit_original_construction(cx,&mut owner,OriginalConstructionDemand{items:1,copy_bytes:bytes,capacity_bytes:0,release_bytes:0,depth:1},|_|Ok((ControlledRetirement::new(input.take().unwrap()).unwrap_or_else(|_|panic!("original Box declares controlled custody")),RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})))?;Ok(())});born+=p.retained_capacity_bytes;freed+=p.released_bytes;let owner=owner.as_mut().unwrap();let mut denials=[false;5];for index in 0..131072{if owner.terminal_is_empty(){break}if cutoff==Some(index){caller.cancel().cancel_now();}let demand=owner.selected_demand(CLOSE.maximum_copy_bytes).unwrap();assert!(demand.copy_bytes<=CLOSE.maximum_copy_bytes,"boxed field must publish a bounded native event: {demand:?}");for axis in 0..5{let mut denied=CLOSE;let active=match axis{0=>{denied.maximum_items=0;true},1=>{denied.maximum_copy_bytes=0;demand.copy_bytes>0},2=>{denied.maximum_capacity_bytes=0;demand.capacity_bytes>0},3=>{denied.maximum_release_bytes=0;demand.release_bytes>0},_=>{denied.maximum_depth=0;demand.depth>0}};if !active{continue}let(_,p)=turn(&mut caller,&mut decoder,denied,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,demand,|grant|owner.step(grant))?;Ok(())}));assert_eq!(p,RetainedCloneProgress::default());denials[axis]=true;}let(_,p)=turn(&mut caller,&mut decoder,CLOSE,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,demand,|grant|owner.step(grant))?;Ok(())}));born+=p.retained_capacity_bytes;freed+=p.released_bytes;assert!(index<131071,"original Box close did not finish: {demand:?}");}assert!(owner.terminal_is_empty());assert!(denials.into_iter().all(|covered|covered));while !decoder.terminal_is_empty(){let result=caller.turn(CLOSE,|cx|cx.with_original_retirement(|cx|{let demand=decoder.retirement_demands(4096)?;close_original_retained_step(cx,demand,|grant|decoder.close_step(grant))?;Ok(())}));result.unwrap();}assert_eq!(born,freed);caller.retire(BIRTH);}}
